-- Откат 20261012120000_domain_action_scopes (запрос пользователя: функция была нужна для
-- лендингов, не для доменов). На момент отката ни одной строки с этими значениями и ни одного
-- домена с автором не было. Postgres не умеет удалять значение enum — тип пересоздаётся.
DELETE FROM "UserPermission" WHERE "permission"::text IN ('DOMAINS_EDIT_OWN','DOMAINS_EDIT_PROJECTS','DOMAINS_DELETE_OWN','DOMAINS_DELETE_PROJECTS');

ALTER TABLE "Domain" DROP CONSTRAINT IF EXISTS "Domain_createdById_fkey";
ALTER TABLE "Domain" DROP COLUMN IF EXISTS "createdById";

ALTER TYPE "Permission" RENAME TO "Permission_old";
CREATE TYPE "Permission" AS ENUM ('LANDINGS_VIEW','LANDINGS_CREATE','LANDINGS_EDIT','LANDINGS_DELETE','PIXELS_VIEW','PIXELS_CREATE','PIXELS_EDIT','PIXELS_DELETE','DOMAINS_VIEW','DOMAINS_CREATE','DOMAINS_EDIT','DOMAINS_DELETE','PUSHES_VIEW','PUSHES_CREATE','PUSHES_SEND','PUSHES_DELETE','AUTOMATIONS_VIEW','AUTOMATIONS_CREATE','AUTOMATIONS_EDIT','AUTOMATIONS_DELETE','AB_TESTS_VIEW','AB_TESTS_CREATE','AB_TESTS_EDIT','AB_TESTS_DELETE','CHANNEL_VIEW','CHANNEL_MANAGE','CLIENTS_VIEW','CLIENTS_EDIT','CLIENTS_DELETE','CLIENTS_EXPORT','STATS_VIEW','STATS_VIEW_REVENUE','STATS_VIEW_TEAM_LEADERBOARDS','PROJECTS_EDIT','CLIENTS_VIEW_CROSS_PROJECT','PERSONAL_BROADCASTS_VIEW','PERSONAL_BROADCASTS_CREATE','PERSONAL_BROADCASTS_SEND','PERSONAL_BROADCASTS_DELETE');
ALTER TABLE "UserPermission" ALTER COLUMN "permission" TYPE "Permission" USING ("permission"::text::"Permission");
DROP TYPE "Permission_old";
